        core = f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="eyebrow">{labels['supply']}</div><h1>{escape(title)}</h1><p>{escape(desc)}</p><div class="actions"><a class="btn" href="{base}/rfq/">{labels['start']}</a><a class="btn alt" href="{base}/suppliers/">{labels['suppliers']}</a></div></div><aside class="signal"><span>RFQ</span><b>BOM · IC · MCU</b><span>IGBT · Bo mạch / 板卡 · Linh kiện / 元器件</span></aside></div></section><section class="soft"><div class="wrap"><h2>{labels['components']}</h2><p class="lead">{labels['intro']}</p><div class="grid">{''.join(f'<article class="card"><h3>{escape(t)}</h3><p>{escape(d)}</p><a href="{base}/{p}/">{labels["start"]} →</a></article>' for p,t,d,h in (VI_PAGES if vi else ZH_PAGES)[4:10])}</div></div></section>{traffic}<section><div class="wrap cta"><h2>{labels['intro']}</h2><a class="btn" href="{base}/rfq/">{labels['rfq']}</a></div></section>'''
